import 'dart:convert';
import 'dart:math';

import 'package:gi_edge_sim/gi_edge_sim.dart';
import 'package:test/test.dart';

/// Vectors from the backend's docs/security/hmac-test-vectors.md (generated by
/// GI Core's real signing code).
void main() {
  const secret = 'golden-test-shared-secret-v1';
  const deviceId = '11111111-1111-4111-8111-111111111111';
  const path = '/api/v1/edge/telemetry';
  const canonicalBody =
      '{"entityKey":"sensor.boiler_supply","temperatureC":21.5}';
  const bodyHash =
      '1e868d294cdb98d2a9ab526030265cfe279a6c427e43a5f0eabc87ccfbdb0cab';

  test('hashes the exact body bytes', () {
    expect(sha256Hex(utf8.encode(canonicalBody)), bodyHash);
  });

  test('builds the golden signing material', () {
    expect(
      signingMaterial(
        path: path,
        bodyHash: bodyHash,
        deviceId: deviceId,
        timestamp: '2026-07-22T12:00:00.000Z',
        nonce: 'deadbeef0000cafe',
        sequence: '42',
      ),
      'POST\n$path\n$bodyHash\n$deviceId\n2026-07-22T12:00:00.000Z\n'
      'deadbeef0000cafe\n42',
    );
  });

  test('signs the valid vector', () {
    final headers = signedHeaders(
      sharedSecret: secret,
      deviceId: deviceId,
      path: path,
      body: utf8.encode(canonicalBody),
      timestamp: '2026-07-22T12:00:00.000Z',
      nonce: 'deadbeef0000cafe',
      sequence: 42,
    );
    expect(
      headers['x-gi-signature'],
      'PIAqNWY_Ar8hwtSAfonTZmbZZEuCmMo3LeJzFyEWb_U',
    );
    expect(headers['x-gi-content-sha256'], bodyHash);
    expect(headers['x-gi-sequence'], '42');
    expect(headers['x-gi-protocol-version'], '1.0');
    expect(headers['content-type'], 'application/json');
  });

  test('signs the stale-timestamp vector', () {
    final headers = signedHeaders(
      sharedSecret: secret,
      deviceId: deviceId,
      path: path,
      body: utf8.encode(canonicalBody),
      timestamp: '2020-01-01T00:00:00.000Z',
      nonce: 'deadbeef0000cafe',
      sequence: 42,
    );
    expect(
      headers['x-gi-signature'],
      '0KPcGlBVfysaND8dgoeDr8skkVJo3ildCt_WPbkbAqk',
    );
  });

  test('another secret gives another signature', () {
    final other = signedHeaders(
      sharedSecret: 'a-completely-different-secret',
      deviceId: deviceId,
      path: path,
      body: utf8.encode(canonicalBody),
      timestamp: '2026-07-22T12:00:00.000Z',
      nonce: 'deadbeef0000cafe',
      sequence: 42,
    );
    expect(
      other['x-gi-signature'],
      isNot('PIAqNWY_Ar8hwtSAfonTZmbZZEuCmMo3LeJzFyEWb_U'),
    );
  });

  test('timestamp has milliseconds and a Z, the nonce 16 hex characters', () {
    expect(
      isoMillis(DateTime.utc(2026, 11, 22, 10, 0, 0, 123, 456)),
      '2026-11-22T10:00:00.123Z',
    );
    expect(newNonce(_Fixed()), matches(RegExp(r'^[0-9a-f]{16}$')));
  });

  test('wire JSON writes doubles with six decimals, keys in order', () {
    expect(
      encodeWireJson({
        'b': 45.5,
        'a': [1, true, null, 'x"y'],
        'n': {'k': 2},
      }),
      r'{"b":45.500000,"a":[1,true,null,"x\"y"],"n":{"k":2}}',
    );
  });
}

class _Fixed implements Random {
  @override
  bool nextBool() => true;

  @override
  double nextDouble() => 0.5;

  @override
  int nextInt(int max) => 171;
}
